import{_ as t,o as a,c as n,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"UC 03 — Media Package & Media Campaign (UC-040 – UC-052)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/03-media-package-campaign.md","filePath":"ba/use-cases/03-media-package-campaign.md"}'),i={name:"ba/use-cases/03-media-package-campaign.md"};function d(o,e,l,g,s,r){return a(),n("div",null,[...e[0]||(e[0]=[c('<h1 id="uc-03-—-media-package-media-campaign-uc-040-–-uc-052" tabindex="-1">UC 03 — Media Package &amp; Media Campaign (<code>UC-040</code> – <code>UC-052</code>) <a class="header-anchor" href="#uc-03-—-media-package-media-campaign-uc-040-–-uc-052" aria-label="Permalink to &quot;UC 03 — Media Package &amp; Media Campaign (`UC-040` – `UC-052`)&quot;">​</a></h1><p>&gt; <a href="./02-agency-workspace.html">&lt;&lt; 02-agency-workspace.md</a> | <a href="./README.html">UC Index</a> | <a href="./../04-media-package-campaign.html">Domain BA Spec: 04-media-package-campaign.md</a> | <a href="./04-content-task-workflow.html">04-content-task-workflow.md &gt;&gt;</a> &gt; &gt; Đồng bộ chuẩn xác 1-đối-1 với <code>Các FR của hệ thống - Feature_Function Requirement.csv</code> và <code>AGENTS.md</code>. Chỉ sử dụng <strong>6 Vai trò Hệ thống Chuẩn (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>)</strong>.</p><hr><h2 id="_1-bang-tong-hop-use-cases-13-ucs" tabindex="-1">1. Bảng Tổng Hợp Use Cases (13 UCs) <a class="header-anchor" href="#_1-bang-tong-hop-use-cases-13-ucs" aria-label="Permalink to &quot;1. Bảng Tổng Hợp Use Cases (13 UCs)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">UC ID</th><th style="text-align:left;">Use Case Title</th><th style="text-align:left;">Canonical Actor(s)</th><th style="text-align:center;">Related FR</th><th style="text-align:left;">Business Rules</th></tr></thead><tbody><tr><td style="text-align:center;"><code>UC-040</code></td><td style="text-align:left;">Create Media Package</td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:center;"><code>3.5.1</code></td><td style="text-align:left;"><code>BR-15, BR-25</code></td></tr><tr><td style="text-align:center;"><code>UC-041</code></td><td style="text-align:left;">View Template Media Package</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.5.2</code></td><td style="text-align:left;"><code>BR-20, BR-25</code></td></tr><tr><td style="text-align:center;"><code>UC-042</code></td><td style="text-align:left;">Request Media Package</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.5.3</code></td><td style="text-align:left;"><code>BR-25, BR-26</code></td></tr><tr><td style="text-align:center;"><code>UC-043</code></td><td style="text-align:left;">Approve Media Package</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.5.4</code></td><td style="text-align:left;"><code>BR-26, BR-27</code></td></tr><tr><td style="text-align:center;"><code>UC-044</code></td><td style="text-align:left;">Create Media Campaign</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;"><code>3.5.5</code></td><td style="text-align:left;"><code>BR-22, BR-27, BR-28</code></td></tr><tr><td style="text-align:center;"><code>UC-045</code></td><td style="text-align:left;">View Media Campaign</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.5.6</code></td><td style="text-align:left;"><code>BR-20, BR-27, BR-28</code></td></tr><tr><td style="text-align:center;"><code>UC-046</code></td><td style="text-align:left;">Update Media Campaign</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.5.7</code></td><td style="text-align:left;"><code>BR-27, BR-28, BR-29, BR-30</code></td></tr><tr><td style="text-align:center;"><code>UC-047</code></td><td style="text-align:left;">Approve Media Campaign</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.5.8</code></td><td style="text-align:left;"><code>BR-28, BR-29</code></td></tr><tr><td style="text-align:center;"><code>UC-048</code></td><td style="text-align:left;">Complete Media Campaign</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;"><code>3.5.9</code></td><td style="text-align:left;"><code>BR-30, BR-32</code></td></tr><tr><td style="text-align:center;"><code>UC-049</code></td><td style="text-align:left;">Create Content Request</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.5.10</code></td><td style="text-align:left;"><code>BR-20, BR-31</code></td></tr><tr><td style="text-align:center;"><code>UC-050</code></td><td style="text-align:left;">Track Request Status</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.5.11</code></td><td style="text-align:left;"><code>BR-31, BR-33</code></td></tr><tr><td style="text-align:center;"><code>UC-051</code></td><td style="text-align:left;">Update Request</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.5.12</code></td><td style="text-align:left;"><code>BR-31, BR-32</code></td></tr><tr><td style="text-align:center;"><code>UC-052</code></td><td style="text-align:left;">Cancel Request</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.5.13</code></td><td style="text-align:left;"><code>BR-31, BR-32</code></td></tr></tbody></table><hr><h2 id="uc-040-—-create-media-package" tabindex="-1">UC-040 — Create Media Package <a class="header-anchor" href="#uc-040-—-create-media-package" aria-label="Permalink to &quot;UC-040 — Create Media Package&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.5.1</code> (3.5 Media Package &amp; Media Campaign)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-25</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG31</code></li><li><strong>Specification &amp; Flow:</strong> Tạo gói dịch vụ truyền thông mẫu hoặc gói tùy chỉnh (Create Media Package — /workspaces/:id/packages). Hệ thống hỗ trợ các gói mẫu theo thời lượng (2 tuần, 3 tuần, 1 tháng...), theo ngân sách hoặc gói trọn gói theo KPI do Admin/Owner thiết lập sẵn; cho phép định nghĩa Tên gói, Thời lượng, Ngân sách dự kiến, Số lượng ấn phẩm/bài đăng cam kết theo từng nền tảng. Khi tạo Workspace bắt buộc phải gắn hoặc nhắc cấu hình Media Package làm cơ sở làm việc với Client (BR-25).</li></ul><hr><h2 id="uc-041-—-view-template-media-package" tabindex="-1">UC-041 — View Template Media Package <a class="header-anchor" href="#uc-041-—-view-template-media-package" aria-label="Permalink to &quot;UC-041 — View Template Media Package&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.5.2</code> (3.5 Media Package &amp; Media Campaign)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-25</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem danh sách và chi tiết các gói truyền thông mẫu (View Template Media Package — /workspaces/:id/packages). Giúp Client hình dung rõ quy mô triển khai, thời lượng thuê Agency, cơ cấu nhân sự và số lượng đầu mục công việc theo 3 nhóm hình thức: (1) Gói theo khung thời gian, (2) Gói theo ngân sách cố định, và (3) Gói ủy thác toàn diện theo KPI (BR-25).</li></ul><hr><h2 id="uc-042-—-request-media-package" tabindex="-1">UC-042 — Request Media Package <a class="header-anchor" href="#uc-042-—-request-media-package" aria-label="Permalink to &quot;UC-042 — Request Media Package&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.5.3</code> (3.5 Media Package &amp; Media Campaign)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-25, BR-26</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG31, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Đề xuất và đàm phán điều chỉnh gói truyền thông (Request Media Package — /workspaces/:id/packages/:packageId). Từ gói mẫu ban đầu, Client và Agency (Owner/Manager) trao đổi, đề xuất chỉnh sửa về mức giá, thời gian triển khai, số lượng bài đăng, sự kiện hoặc hình thức truyền thông qua từng vòng đàm phán cho đến khi hai bên thống nhất phương án cuối cùng (BR-26).</li></ul><hr><h2 id="uc-043-—-approve-media-package" tabindex="-1">UC-043 — Approve Media Package <a class="header-anchor" href="#uc-043-—-approve-media-package" aria-label="Permalink to &quot;UC-043 — Approve Media Package&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.5.4</code> (3.5 Media Package &amp; Media Campaign)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-26, BR-27</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG31, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Phê duyệt chốt gói truyền thông (Approve Media Package — /workspaces/:id/packages/:packageId). Khi cả hai bên (Agency và Client) đồng thuận xác nhận toàn bộ các điều khoản, chi phí và hạng mục bàn giao của gói truyền thông, hệ thống khóa phiên bản gói ở trạng thái APPROVED làm căn cứ lập chiến dịch truyền thông chi tiết (BR-26).</li></ul><hr><h2 id="uc-044-—-create-media-campaign" tabindex="-1">UC-044 — Create Media Campaign <a class="header-anchor" href="#uc-044-—-create-media-campaign" aria-label="Permalink to &quot;UC-044 — Create Media Campaign&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.5.5</code> (3.5 Media Package &amp; Media Campaign)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code></li><li><strong>Business Rules:</strong> <code>BR-22, BR-27, BR-28</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG32, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Khởi tạo Kế hoạch Chiến dịch Truyền thông chi tiết dựa trên Media Package đã được phê duyệt (Create Media Campaign — /workspaces/:id/campaigns/new). Đóng vai trò là bản chiến lược thực thi chi tiết phù hợp với thương hiệu của Client: xác định mục tiêu chiến dịch, lộ trình thời gian (Start/End Date), danh sách các đầu mục bài viết dự kiến (tiêu đề, nền tảng đăng tải, định dạng, lịch dự kiến) (BR-27).</li></ul><hr><h2 id="uc-045-—-view-media-campaign" tabindex="-1">UC-045 — View Media Campaign <a class="header-anchor" href="#uc-045-—-view-media-campaign" aria-label="Permalink to &quot;UC-045 — View Media Campaign&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.5.6</code> (3.5 Media Package &amp; Media Campaign)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-27, BR-28</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem chi tiết Kế hoạch Chiến dịch Truyền thông (View Media Campaign — /workspaces/:id/campaigns/:campaignId). Hiển thị thông tin tổng quan chiến dịch, gói truyền thông gốc, danh sách toàn bộ các hạng mục công việc dự kiến, lịch sử các phiên bản chỉnh sửa và luồng phản hồi giữa Agency với Client (BR-27).</li></ul><hr><h2 id="uc-046-—-update-media-campaign" tabindex="-1">UC-046 — Update Media Campaign <a class="header-anchor" href="#uc-046-—-update-media-campaign" aria-label="Permalink to &quot;UC-046 — Update Media Campaign&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.5.7</code> (3.5 Media Package &amp; Media Campaign)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-27, BR-28, BR-29, BR-30</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG32, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Cập nhật nội dung Kế hoạch Chiến dịch Truyền thông và gửi phản hồi điều chỉnh trước khi phê duyệt chính thức (Update Media Campaign — /workspaces/:id/campaigns/:campaignId). Cho phép Agency chỉnh sửa danh sách hạng mục bài viết, mốc thời gian, kênh phân phối theo góp ý của Client khi chiến dịch đang ở trạng thái DRAFT hoặc PENDING_APPROVAL (BR-27).</li></ul><hr><h2 id="uc-047-—-approve-media-campaign" tabindex="-1">UC-047 — Approve Media Campaign <a class="header-anchor" href="#uc-047-—-approve-media-campaign" aria-label="Permalink to &quot;UC-047 — Approve Media Campaign&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.5.8</code> (3.5 Media Package &amp; Media Campaign)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-28, BR-29</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG33, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Phê duyệt và kích hoạt triển khai Chiến dịch Truyền thông (Approve Media Campaign — /workspaces/:id/campaigns/:campaignId). Ngay khi cả hai bên đồng ý phê duyệt chiến lược, hệ thống chuyển trạng thái chiến dịch sang ACTIVE và tự động đẩy toàn bộ các hạng mục công việc trong Media Campaign vào bảng Task Backlog của Workspace (tương tự Jira Backlog) với tiêu đề và khung thời gian dự kiến để Manager tiếp tục phân rã chi tiết (BR-29).</li></ul><hr><h2 id="uc-048-—-complete-media-campaign" tabindex="-1">UC-048 — Complete Media Campaign <a class="header-anchor" href="#uc-048-—-complete-media-campaign" aria-label="Permalink to &quot;UC-048 — Complete Media Campaign&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.5.9</code> (3.5 Media Package &amp; Media Campaign)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code></li><li><strong>Business Rules:</strong> <code>BR-30, BR-32</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG34, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Nghiệm thu và hoàn tất Chiến dịch Truyền thông (Complete Media Campaign — /workspaces/:id/campaigns/:campaignId). Chuyển trạng thái chiến dịch từ ACTIVE sang COMPLETED sau khi hoàn thành bàn giao, đồng thời hệ thống tự động hủy (CANCELLED) toàn bộ các yêu cầu phát sinh (Content Requests) còn đang treo ở trạng thái PENDING thuộc chiến dịch đó (BR-30).</li></ul><hr><h2 id="uc-049-—-create-content-request" tabindex="-1">UC-049 — Create Content Request <a class="header-anchor" href="#uc-049-—-create-content-request" aria-label="Permalink to &quot;UC-049 — Create Content Request&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.5.10</code> (3.5 Media Package &amp; Media Campaign)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-31</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG35</code></li><li><strong>Specification &amp; Flow:</strong> Tạo yêu cầu nội dung bổ sung/phát sinh ngoài kế hoạch ban đầu (Create Content Request — /workspaces/:id/requests/new). Cho phép Client hoặc Manager gửi yêu cầu bài viết/sự kiện mới kèm tiêu đề, mô tả, nền tảng mong muốn, hạn chót và tệp đính kèm. Yêu cầu khởi tạo ở trạng thái PENDING để chờ Manager xem xét và ghi nhận làm căn cứ tính khối lượng công việc bổ sung (BR-31).</li></ul><hr><h2 id="uc-050-—-track-request-status" tabindex="-1">UC-050 — Track Request Status <a class="header-anchor" href="#uc-050-—-track-request-status" aria-label="Permalink to &quot;UC-050 — Track Request Status&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.5.11</code> (3.5 Media Package &amp; Media Campaign)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-31, BR-33</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG35, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Theo dõi và điều phối trạng thái của Yêu cầu nội dung (Track Request Status — /workspaces/:id/requests). Gồm 4 trạng thái chuẩn: PENDING -&gt; IN_PROGRESS -&gt; ACCEPTED (hoặc DENIED). Chỉ phía Agency (Manager/Owner) mới có quyền chuyển trạng thái xét duyệt; khi chuyển sang ACCEPTED, hệ thống tự động sinh một Task tương ứng đẩy vào danh sách Task Backlog của Workspace để phân công thực hiện (BR-31).</li></ul><hr><h2 id="uc-051-—-update-request" tabindex="-1">UC-051 — Update Request <a class="header-anchor" href="#uc-051-—-update-request" aria-label="Permalink to &quot;UC-051 — Update Request&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.5.12</code> (3.5 Media Package &amp; Media Campaign)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-31, BR-32</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG35, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Chỉnh sửa nội dung của Yêu cầu phát sinh (Update Request — /workspaces/:id/requests/:requestId). Người tạo chỉ được phép cập nhật tiêu đề, mô tả, hạn mong muốn hoặc tệp tham khảo khi yêu cầu đang ở trạng thái PENDING; một khi Agency đã chuyển sang IN_PROGRESS, ACCEPTED hoặc DENIED thì nội dung yêu cầu bị khóa không cho sửa (BR-32).</li></ul><hr><h2 id="uc-052-—-cancel-request" tabindex="-1">UC-052 — Cancel Request <a class="header-anchor" href="#uc-052-—-cancel-request" aria-label="Permalink to &quot;UC-052 — Cancel Request&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.5.13</code> (3.5 Media Package &amp; Media Campaign)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-31, BR-32</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG35, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Hủy yêu cầu nội dung phát sinh (Cancel Request — /workspaces/:id/requests/:requestId). Chỉ cho phép hủy yêu cầu khi đang ở trạng thái PENDING (chuyển trạng thái sang CANCELLED); các yêu cầu đã chuyển sang xử lý hoặc đã duyệt không được phép xóa/hủy (BR-32).</li></ul>',44)])])}const p=t(i,[["render",d]]);export{u as __pageData,p as default};
